<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';

use App\Core\Auth;
use App\Core\Csrf;
use App\Core\Database;
use App\Services\DanceCupCategoryEditService;
use App\Services\DanceCupScoringService;

Auth::requireAdmin();
$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';
if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}
$id=(int)($_GET['id']??$_POST['id']??0);$pdo=Database::connection();DanceCupScoringService::ensureWorkspaceTables($pdo,$test);$tables=DanceCupScoringService::tables($test);$suffix=$test?'&data_mode=test':'';$error='';$notice='';
try{
 $state=DanceCupCategoryEditService::state($pdo,$id,$test);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'save');
  if($action==='unlock'){DanceCupCategoryEditService::unlock($pdo,$id,(string)($_POST['unlock_reason']??''),(string)($_POST['confirmation']??''),(int)(Auth::user()['id']??0),$test);header('Location: edit-category.php?id='.$id.$suffix.'&unlocked=1',true,303);exit;}
  $criteria=[];$names=(array)($_POST['criterion_name']??[]);$maxima=(array)($_POST['criterion_max']??[]);foreach($names as $index=>$name)if(trim((string)$name)!==''||trim((string)($maxima[$index]??''))!=='')$criteria[]=['name'=>trim((string)$name),'max'=>(float)($maxima[$index]??0)];$result=DanceCupCategoryEditService::save($pdo,$id,$_POST,$criteria,(string)($_POST['reset_confirmation']??''),(int)(Auth::user()['id']??0),$test);header('Location: edit-category.php?id='.$id.$suffix.'&saved=1'.($result['scores_reset']?'&reset=1':''),true,303);exit;
 }
}catch(Throwable $e){$error=$e->getMessage();$state=DanceCupCategoryEditService::state($pdo,$id,$test);}
if(isset($_GET['unlocked']))$notice='Category editing unlocked temporarily. Judge scoring is paused until you save.';if(isset($_GET['saved']))$notice=isset($_GET['reset'])?'Category updated and incompatible scores safely reset.':'Category updated. Existing marks were preserved.';
$event=$pdo->prepare("SELECT name FROM {$tables['events']} WHERE id=:event");$event->execute(['event'=>$state['event_id']]);$eventName=(string)$event->fetchColumn();$criteriaQ=$pdo->prepare("SELECT criterion_name,maximum_points FROM {$tables['criteria']} WHERE competition_id=:competition ORDER BY sort_order,id");$criteriaQ->execute(['competition'=>$id]);$criteria=$criteriaQ->fetchAll();$started=!empty($state['scoring_started']);$unlocked=!empty($state['edit_unlocked_at']);$published=in_array((string)$state['status'],['submitted','pending_approval','approved'],true);$canEdit=!$published&&(!$started||$unlocked);$csrf=Csrf::token();$back=$state['scoring_mode']==='automatic'?'automatic-setup.php':'category.php';
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit <?=e($state['category_name'])?> | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=460" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=505"></script><style>body{background:#eef3f9}.edit-hero{border:0;border-radius:22px;background:linear-gradient(125deg,#101d35,#19396d 58%,#621d3e);color:#fff}.edit-card{border:1px solid #dae3ef;border-radius:18px}.criterion-row{display:grid;grid-template-columns:minmax(0,1fr) 145px 44px;gap:8px;margin-bottom:8px}.lock-card{border-left:5px solid #dc3545}.unlock-card{border-left:5px solid #e0a800}@media(max-width:575px){.criterion-row{grid-template-columns:minmax(0,1fr) 100px 42px}}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./<?=$test?'?data_mode=test':''?>">BDC Dance Cup</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4" style="max-width:1050px"><div class="mb-3"><a href="<?=e($back)?>?id=<?=$id?><?=$suffix?>">← Back to Category</a></div><section class="edit-hero p-4 mb-4"><span class="badge text-bg-warning"><?=$test?'TEST · ':''?>CATEGORY EDITOR</span><h1 class="h3 mt-2 mb-1"><?=e($state['category_name'])?></h1><p class="mb-0 opacity-75"><?=e($eventName)?> · <?=e(ucfirst($state['scoring_mode']))?> Scoring</p></section><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
