<?php elseif($started&&!$unlocked):?><section class="card edit-card lock-card"><div class="card-body p-4"><span class="badge text-bg-danger">SCORING STARTED · EDIT LOCKED</span><h2 class="h5 mt-3">Unlock category editing</h2><p class="text-muted">Unlocking pauses judge scoring but preserves every mark. Saving metadata keeps marks. Changing criteria requires a separate score reset confirmation.</p><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="action" value="unlock"><div class="col-md-8"><label class="form-label">Reason for unlocking</label><input class="form-control" name="unlock_reason" minlength="8" required placeholder="Explain what must be corrected"></div><div class="col-md-4"><label class="form-label">Type UNLOCK</label><input class="form-control" name="confirmation" autocomplete="off" required></div><div class="col-12"><button class="btn btn-danger" onclick="return confirm('Pause judge scoring and unlock this category for editing?')">Unlock Category for Editing</button></div></form></div></section>
<?php else:?><section class="card edit-card <?=$unlocked?'unlock-card':''?>"><div class="card-body p-4"><?php if($unlocked):?><div class="alert alert-warning"><strong>Editing temporarily unlocked.</strong> Judge scoring is paused. Saving will automatically close the editing window.</div><?php endif;?><form method="post" id="categoryEditForm"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="action" value="save"><div class="row g-3"><div class="col-12"><label class="form-label">Category Name</label><input class="form-control" name="category_name" required value="<?=e($state['category_name'])?>"></div><div class="col-md-4"><label class="form-label">Dance Style</label><select class="form-select" name="dance_style"><?php foreach(['salsa'=>'Salsa','bachata'=>'Bachata','cha_cha'=>'Cha Cha','other'=>'Other / Custom'] as $value=>$label):?><option value="<?=$value?>" <?=$state['dance_style']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Entry Type</label><select class="form-select" name="entry_type"><?php foreach(['solo'=>'Solo','couple'=>'Couple','duo'=>'Duo','pro_am'=>'Pro Am','team'=>'Team'] as $value=>$label):?><option value="<?=$value?>" <?=$state['entry_type']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Level</label><select class="form-select" name="competition_level"><?php foreach(['open'=>'Open','professional'=>'Professional','pro_am'=>'Pro Am','intermediate'=>'Intermediate','amateur'=>'Amateur'] as $value=>$label):?><option value="<?=$value?>" <?=$state['competition_level']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Category Gender</label><select class="form-select" name="gender_eligibility"><?php foreach(['mixed'=>'Mixed Gender','female_only'=>'Female Only','male_only'=>'Male Only'] as $value=>$label):?><option value="<?=$value?>" <?=$state['gender_eligibility']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Performance Type</label><select class="form-select" name="performance_type"><?php foreach(['showcase'=>'Showcase','classic'=>'Classic','cabaret'=>'Cabaret','shines'=>'Shines','just_dance'=>'Just Dance'] as $value=>$label):?><option value="<?=$value?>" <?=$state['performance_type']===$value?'selected':''?>><?=ucwords(str_replace('_',' ',$label))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Round</label><select class="form-select" name="round_name"><?php foreach(['qualifier'=>'Qualifier','quarterfinal'=>'Quarterfinal','semifinal'=>'Semifinal','final'=>'Final'] as $value=>$label):?><option value="<?=$value?>" <?=$state['round_name']===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-12"><div class="d-flex justify-content-between"><label class="form-label fw-bold">Scoring Criteria</label><span class="badge text-bg-dark">Total: <span id="criteriaTotal">0</span></span></div><div id="criteriaRows"><?php foreach($criteria as $criterion):?><div class="criterion-row"><input class="form-control criterion-name" name="criterion_name[]" required value="<?=e($criterion['criterion_name'])?>"><input class="form-control criterion-max" type="number" name="criterion_max[]" min="0.01" max="1000" step="0.01" required value="<?=e(rtrim(rtrim(number_format((float)$criterion['maximum_points'],2,'.',''),'0'),'.'))?>"><button class="btn btn-outline-danger remove-criterion" type="button">×</button></div><?php endforeach;?></div><button class="btn btn-sm btn-outline-primary" type="button" id="addCriterion">+ Add Criterion</button><?php if((int)$state['mark_count']>0):?><div class="alert alert-danger mt-3 mb-0"><strong>Criteria protection:</strong> If you change criterion names, order or maximum points, type <strong>RESET SCORES</strong> below. Metadata-only changes preserve all existing marks.</div><label class="form-label mt-2">Score-reset confirmation, only required when criteria change</label><input class="form-control" name="reset_confirmation" autocomplete="off" placeholder="RESET SCORES"><?php endif;?></div><div class="col-12"><button class="btn btn-success btn-lg" onclick="return confirm('Save these Dance Cup category changes?')">Save Category Changes</button></div></div></form></div></section><?php endif;?></main><script>const rows=document.getElementById('criteriaRows'),total=document.getElementById('criteriaTotal');function recalc(){if(total)total.textContent=[...document.querySelectorAll('.criterion-max')].reduce((sum,input)=>sum+(Number(input.value)||0),0).toFixed(2).replace(/\.00$/,'')}function bind(row){row.querySelector('.criterion-max').addEventListener('input',recalc);row.querySelector('.remove-criterion').addEventListener('click',()=>{row.remove();recalc()})}document.querySelectorAll('.criterion-row').forEach(bind);document.getElementById('addCriterion')?.addEventListener('click',()=>{const row=document.createElement('div');row.className='criterion-row';row.innerHTML='<input class="form-control criterion-name" name="criterion_name[]" required><input class="form-control criterion-max" type="number" name="criterion_max[]" min="0.01" max="1000" step="0.01" required><button class="btn btn-outline-danger remove-criterion" type="button">×</button>';rows.appendChild(row);bind(row)});recalc()</script></body></html>
